package pro.livemic.studio;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;

/** Builds a portable, deterministic document package from a detached project snapshot. */
final class ComposerLlmExport {
    private ComposerLlmExport() {}
    static void write(ComposerProject p,String request,OutputStream output)throws Exception {
        p.validate();
        LinkedHashMap<String,byte[]> files=new LinkedHashMap<>();
        put(files,"project.json",p.json().toString(2)+"\n");
        put(files,"arrangement.md",arrangement(p));
        put(files,"README.md",readme());
        put(files,"llm-prompt.md",prompt(request));
        put(files,"schema.json",schema().toString(2)+"\n");
        JSONObject hashes=new JSONObject();
        for(Map.Entry<String,byte[]> entry:files.entrySet())hashes.put(entry.getKey(),hex(MessageDigest.getInstance("SHA-256").digest(entry.getValue())));
        JSONObject manifest=new JSONObject().put("format","livevault-llm-export").put("version",1).put("projectVersion",ComposerProject.VERSION).put("projectId",p.id).put("parts",p.parts.size()).put("bars",p.totalBars()).put("timeUnit","quarter notes").put("sha256",hashes);
        put(files,"manifest.json",manifest.toString(2)+"\n");
        try(ZipOutputStream zip=new ZipOutputStream(output,StandardCharsets.UTF_8)){
            for(Map.Entry<String,byte[]> entry:files.entrySet()){ZipEntry item=new ZipEntry(entry.getKey());item.setTime(0);zip.putNextEntry(item);zip.write(entry.getValue());zip.closeEntry();}
        }
    }
    private static void put(Map<String,byte[]> files,String name,String value){files.put(name,value.getBytes(StandardCharsets.UTF_8));}
    private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    static String readme(){return "# Live Vault AI export\n\nAttach this ZIP to ChatGPT or another AI, and ask for the musical changes you want. llm-prompt.md contains a suggested request; you can edit it. project.json is the complete project snapshot, arrangement.md is a human-readable overview, and schema.json describes the format. manifest.json contains file hashes. No audio is included. Notes beyond the current part and expression points beyond note ends are preserved; playback clips or ignores those portions.\n\nAsk the AI for the complete project JSON as plain JSON without Markdown fences. Save its response as a UTF-8 .json file (maximum 8 MiB), then use Import JSON in Live Vault. Review the preview and choose Open new copy to apply it; the current project is saved to your library first.\n";}
    private static String rhythm(int index){return new String[]{"Pop 8-beat","Pop 16-beat","Shuffle","R&B","Rock","Bossa nova","Waltz","6/8 ballad"}[index];}
    private static String category(TrackConfig t){if(t.drums())return "Drums";return new String[]{"Piano","Chromatic percussion","Organ","Guitar","Bass","Strings","Ensemble","Brass","Reed","Pipe","Synth lead","Synth pad","Synth effects","Ethnic","Percussive","Sound effects"}[t.family()];}
    private static String pattern(TrackConfig t){if(t.drums())return "rhythm pattern";String[] labels=t.family()==3?new String[]{"strum","arpeggio","muted strum","power chord"}:t.family()==4?new String[]{"root","root and fifth","octave","walking"}:t.family()>=7&&t.family()<=10?new String[]{"chord-tone melody","long notes"}:new String[]{"block chords","arpeggio","sustained chords"};return t.pattern<labels.length?labels[t.pattern]:"other ("+t.pattern+")";}
    static String arrangement(ComposerProject p){
        String[] meters={"4/4","3/4","6/8"},scales={"major","natural minor","harmonic minor","Dorian","Mixolydian"};
        StringBuilder s=new StringBuilder("# Arrangement\n\n");
        s.append("Project: ").append(p.name).append("\nKey: ").append(MusicTheory.ROOTS[p.key]).append(' ').append(scales[p.scale]).append("\nMeter: ").append(meters[p.meter]).append("\nBPM: ").append(p.bpm).append(p.meter==2?" dotted quarters/minute (quarter BPM = "+MusicTheory.quarterBpm(p.bpm,p.meter)+")":" quarter notes/minute").append("\nSeed: ").append(p.seed).append("\nAll beats and phrase offsets are quarter notes; each bar has ").append(MusicTheory.barBeats(p.meter)).append(" quarter notes. Split chords start at bar beat 0 and the meter-specific split shown below.\n\n## Form\n");
        int bar=1;for(ComposerProject.Order o:p.order){ComposerProject.Part part=p.part(o.part);s.append("- Bar ").append(bar).append(": ").append(part.label).append(" (ID ").append(part.id).append("), ").append(part.bars).append(" bars × ").append(o.repeats).append("\n");bar+=part.bars*o.repeats;}
        for(ComposerProject.Part part:p.parts){s.append("\n## Part ").append(part.label).append(" (").append(part.id).append(")\nRhythm ").append(part.rhythm).append(" (").append(rhythm(part.rhythm)).append("), energy ").append(part.energy).append(", humanize ").append(part.humanize).append(", fill ").append(part.fill).append("\n\n");
            for(int b=0;b<part.chords.size();b++){s.append("- Bar ").append(b+1).append(": ");List<ComposerProject.Chord> chords=part.chords.get(b);for(int i=0;i<chords.size();i++){if(i>0)s.append(" | ");ComposerProject.Chord c=chords.get(i);s.append("beat ").append(i==0?"0":Double.toString(MusicTheory.split(p.meter))).append(' ').append(c.label(p)).append(c.automatic?" (automatic)":" (manual)");}s.append('\n');}
            s.append("\nTracks (no explicit pitch ranges are stored; phrase note ranges are shown):\n");
            for(TrackConfig t:part.tracks){int low=128,high=-1,notes=0;for(VoicePhrase phrase:part.phrases)if(phrase.trackId.equals(t.id))for(VoicePhrase.Note n:phrase.notes){low=Math.min(low,n.midi);high=Math.max(high,n.midi);notes++;}s.append("- ").append(t.name).append(" [").append(t.id).append("]: ").append(t.voice?"recorded voice phrase":t.drums()?"drums":"instrument").append(", GM program ").append(t.program).append(" (").append(t.drums()?"drum kit":InstrumentCatalog.GM[t.program]).append("; zero-based), category ").append(category(t)).append(", bank ").append(t.bank).append(", pattern ").append(t.pattern).append(" (").append(pattern(t)).append("), volume ").append(t.volume).append(", pan ").append(t.pan).append(", muted ").append(t.muted);if(notes>0)s.append(", ").append(notes).append(" phrase notes, MIDI ").append(low).append("–").append(high);s.append('\n');}
        }return s.toString();
    }
    static String prompt(String request){return "# Live Vault arrangement improvement request\n\nUse project.json as the complete source of truth and schema.json as the v1 format. arrangement.md is a readable overview. Suggest musical improvements that respect the form, timing, instrument roles and playable ranges. Preserve manually selected chords and all recorded phrases and expression unless the request explicitly asks to change them. Return only the complete revised project as plain JSON without Markdown fences or surrounding commentary, retaining IDs and all required fields. Cross-references must remain valid; total ordered bars must not exceed 256. Save the JSON as a UTF-8 file and use Import JSON in Live Vault to preview and open a new copy.\n\n## User request\n\n"+(request==null||request.trim().isEmpty()?"Suggest a tasteful improvement while preserving the existing musical intent.":request.trim())+"\n";}
    private static JSONObject number(String type,double min,double max)throws JSONException{return new JSONObject().put("type",type).put("minimum",min).put("maximum",max);}
    private static JSONObject type(String type)throws JSONException{return new JSONObject().put("type",type);}
    private static JSONObject ref(String name)throws JSONException{return new JSONObject().put("$ref","#/$defs/"+name);}
    private static JSONObject array(JSONObject item,int min,int max)throws JSONException{return new JSONObject().put("type","array").put("items",item).put("minItems",min).put("maxItems",max);}
    private static JSONObject object(JSONObject properties)throws JSONException{JSONArray required=new JSONArray();Iterator<String> keys=properties.keys();while(keys.hasNext())required.put(keys.next());return new JSONObject().put("type","object").put("properties",properties).put("required",required).put("additionalProperties",false);}
    static JSONObject schema()throws JSONException{
        JSONObject integer=type("integer"),string=type("string"),bool=type("boolean"),num=type("number"),midi=number("integer",0,127),unit=number("number",0,1),degree=number("integer",0,6),quality=number("integer",0,10);
        JSONObject chord=object(new JSONObject().put("root",number("integer",0,11)).put("quality",quality).put("bass",number("integer",-1,11)).put("degree",degree).put("automatic",bool).put("seventh",bool).put("dominant",bool));
        JSONObject track=object(new JSONObject().put("id",string).put("name",string).put("program",midi).put("bank",new JSONObject().put("enum",new JSONArray().put(0).put(128))).put("pattern",number("integer",0,3)).put("volume",unit).put("pan",number("number",-1,1)).put("muted",bool).put("voice",bool));
        JSONObject point=new JSONObject().put("type","array").put("prefixItems",new JSONArray().put(number("number",0,1024)).put(number("number",-12800,12800)).put(unit)).put("minItems",3).put("maxItems",3).put("description","[offset in quarter notes, bend in cents, expression]");
        JSONObject note=object(new JSONObject().put("beat",number("number",0,1024)).put("length",number("number",.01,1024)).put("offset",number("number",0,1024)).put("midi",midi).put("velocity",number("integer",1,127)).put("degree",number("integer",-1,6)).put("quality",quality).put("automatic",bool).put("bend",number("number",-12800,12800)).put("expression",unit).put("curve",array(point,0,12000)));
        JSONObject phrase=object(new JSONObject().put("trackId",string).put("quantize",new JSONObject().put("enum",new JSONArray().put(0).put(8).put(16))).put("chordMode",bool).put("notes",array(ref("note"),0,20000)));
        JSONObject part=object(new JSONObject().put("id",string).put("label",string).put("bars",new JSONObject().put("enum",new JSONArray().put(4).put(8).put(16))).put("rhythm",number("integer",0,7)).put("energy",unit).put("humanize",unit).put("fill",bool).put("chords",array(array(ref("chord"),1,2),4,16)).put("tracks",array(ref("track"),0,8)).put("phrases",array(ref("phrase"),0,Integer.MAX_VALUE)));
        JSONObject voice=object(new JSONObject().put("program",midi).put("mode",number("integer",0,1)).put("octave",number("integer",-3,3)).put("response",number("integer",0,1)).put("quality",number("integer",-1,10)).put("quantize",new JSONObject().put("enum",new JSONArray().put(0).put(8).put(16))).put("autoRange",bool).put("snap",bool).put("rhythm",bool).put("mixVoice",bool).put("confidence",number("number",.5,.990001)).put("gate",number("number",.000999999,.100001)));
        JSONObject order=object(new JSONObject().put("part",string).put("repeats",number("integer",1,64)));
        JSONObject root=object(new JSONObject().put("version",new JSONObject().put("const",1)).put("id",string).put("name",string).put("key",number("integer",0,11)).put("scale",number("integer",0,4)).put("bpm",number("integer",40,240)).put("meter",number("integer",0,2)).put("seed",integer).put("parts",array(ref("part"),1,8)).put("order",array(ref("order"),1,64)).put("voice",ref("voice")));
        return root.put("$schema","https://json-schema.org/draft/2020-12/schema").put("title","Live Vault Composer project v1").put("description","Pitch classes C=0 through B=11. Scale: 0 major, 1 natural minor, 2 harmonic minor, 3 Dorian, 4 Mixolydian. Chord quality: 0 major, 1 minor, 2 diminished, 3 augmented, 4 sus2, 5 sus4, 6 dominant 7, 7 major 7, 8 minor 7, 9 half-diminished 7, 10 add9. Degree is zero-based. Meter: 0=4/4, 1=3/4, 2=6/8; BPM counts dotted quarters in 6/8, quarter notes otherwise. Phrase beat, length, offset and curve offsets are quarter notes; bend is cents. Older edits may leave notes outside the current part or expression points beyond the note length; preserve them because playback clips or ignores them. Programs are zero-based GM; bank 128 is drums. Rhythm: 0 pop 8-beat, 1 pop 16-beat, 2 shuffle, 3 R&B, 4 rock, 5 bossa nova, 6 waltz, 7 6/8 ballad. Pattern by family: guitar 0 strum, 1 arpeggio, 2 muted strum, 3 power chord; bass 0 root, 1 root/fifth, 2 octave, 3 walking; brass/reed/pipe/synth lead 0 chord-tone melody, 1 long notes; other instruments 0 block chords, 1 arpeggio, 2 sustained chords; drums follow the rhythm. Part chord count must equal bars; order.part and phrase.trackId must reference existing IDs; unique track IDs across parts <=8, ordered bars <=256, cumulative notes <=100000, cumulative curve points <=200000, and curve offsets must be nondecreasing. These cross-field constraints require semantic validation.").put("$defs",new JSONObject().put("chord",chord).put("track",track).put("note",note).put("phrase",phrase).put("part",part).put("voice",voice).put("order",order));
    }
}
